#!/usr/bin/env python3
from pathlib import Path
import sys

if len(sys.argv) != 4:
    raise SystemExit('usage: apply_v18_safe_root_selector.py SEARCH.py SCORE_BAND STATIC_MARGIN')
p = Path(sys.argv[1])
score_band = int(sys.argv[2])
static_margin = int(sys.argv[3])
if not (1 <= score_band <= 40):
    raise SystemExit('SCORE_BAND must be 1..40')
if not (1 <= static_margin <= 80):
    raise SystemExit('STATIC_MARGIN must be 1..80')
s = p.read_text()

old = '''        # Do not start an iteration that plainly cannot fit. CPU-time measurement makes this much\n        # more reliable than the old node-growth forecast; still require a generous 1.65x margin.\n        remaining_ticks = hard_deadline - now_ticks\n        if depth >= 5 and remaining_ticks < int(float(iteration_ticks) * 1.65):\n            break\n\n    return best_move, best_score, completed_depth, int(nodes[0])\n'''

new = f'''        # Do not start an iteration that plainly cannot fit. CPU-time measurement makes this much\n        # more reliable than the old node-growth forecast; still require a generous 1.65x margin.\n        remaining_ticks = hard_deadline - now_ticks\n        if depth >= 5 and remaining_ticks < int(float(iteration_ticks) * 1.65):\n            break\n\n    # V18 safe root selector. The normal iterative/PVS search above is completely untouched.\n    # Only after the final completed iteration may the engine inspect its own one-ply structural\n    # evaluation for an ordinary quiet alternative. That alternative must have a meaningful static\n    # edge, and then receives an independent full-window verification at the completed depth. It can\n    # replace the searched move only inside a very small verified score band. If the extra search\n    # cannot finish inside the original hard node/deadline budget, the ordinary result is preserved.\n    if completed_depth >= 5 and abs(best_score) < MATE_THRESHOLD:\n        structural_move = -1\n        structural_score = -INFINITY\n        selected_static = -INFINITY\n        for selector_index in range(count):\n            selector_move = int(move_stack[0, selector_index])\n            if _is_tactical(board, selector_move):\n                continue\n            _advance_eval_state_into(board, side, selector_move, eval_stack[0], eval_stack[1])\n            selector_static = -_evaluate_state(-side, eval_stack[1])\n            if selector_move == best_move:\n                selected_static = selector_static\n            if selector_static > structural_score:\n                structural_score = selector_static\n                structural_move = selector_move\n\n        if (\n            structural_move >= 0\n            and structural_move != best_move\n            and selected_static > -INFINITY\n            and structural_score >= selected_static + {static_margin}\n            and int(nodes[0]) < max_nodes\n            and int(_CPU_CLOCK()) < hard_deadline\n        ):\n            selector_move = structural_move\n            move_context_stack[0] = np.int16(_quiet_history_context(board, selector_move))\n            selector_child_depth = completed_depth - 1\n            if completed_depth == 1 and _quiet_pawn_relative_rank(board, selector_move) == 6:\n                selector_child_depth = completed_depth\n            selector_halfmove = _next_halfmove_clock(board, selector_move, halfmove_clock)\n            _advance_eval_state_into(board, side, selector_move, eval_stack[0], eval_stack[1])\n            selector_castling, selector_ep, selector_captured, selector_captured_square = make_move_inplace(\n                board, side, castling, ep_square, selector_move\n            )\n            path_keys[1] = _child_position_key(\n                board, side, castling, ep_square, selector_move, selector_castling, selector_ep,\n                selector_captured, selector_captured_square, path_keys[0]\n            )\n            history_contexts[1] = _child_history_context(\n                history_contexts[0], path_keys[0], selector_halfmove\n            )\n            selector_score, selector_aborted = _negamax(\n                board, -side, selector_castling, selector_ep, selector_halfmove, selector_child_depth,\n                -INFINITY, INFINITY, np.int64(1), nodes, max_nodes, hard_deadline,\n                pseudo_stack, move_stack, score_stack, eval_stack, history_keys, history_count, path_keys,\n                killers, quiet_history, move_context_stack, hash_keys, hash_moves, history_contexts,\n                student_edges, tt_table,\n            )\n            undo_move_inplace(board, side, selector_move, selector_captured, selector_captured_square)\n            if not selector_aborted:\n                selector_score = -selector_score\n                if selector_score >= best_score - {score_band}:\n                    best_move = selector_move\n                    best_score = selector_score\n\n    return best_move, best_score, completed_depth, int(nodes[0])\n'''

if s.count(old) != 1:
    raise SystemExit(f'safe-root-selector patch mismatch: {s.count(old)}')
p.write_text(s.replace(old, new, 1))
